```python
def add_contact(contact_book, name, phone_number):
    """Add a contact to the phonebook dictionary."""
    if name in contact_book:
        print(f"Contact {name} already exists. Contact added successfully.")
    else:
        contact_book[name] = phone_number
        print(f"Contact added successfully. Phone number for {name} is {phone_number}.")


def remove_contact(contact_book, name):
    """Remove a contact from the phonebook dictionary."""
    if name in contact_book:
        del contact_book[name]
        print(f"Contact removed successfully. Goodbye, {name}!")
    else:
        print(f"Contact {name} not found. Contact not removed.")


def search_contact(contact_book, name):
    """Search for a contact in the phonebook dictionary."""
    if name in contact_book:
        print(f"Contact found. Phone number for {name} is {contact_book[name]}.")
    else:
        print(f"Contact {name} not found. Contact not displayed.")


def main():
    """Run the phonebook program until the user chooses to exit."""
    contact_book = {}

    while True:
        print("\n--- Phonebook ---")
        print("1. Add contact")
        print("2. Remove contact")
        print("3. Search contact")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter name: ")
            phone_number = input("Enter phone number: ")
            add_contact(contact_book, name, phone_number)

        elif choice == "2":
            name = input("Enter name to remove: ")
            remove_contact(contact_book, name)

        elif choice == "3":
            name = input("Enter name to search: ")
            search_contact(contact_book, name)

        elif choice == "4":
            print("Exiting the program...")
            break

        else:
            print("Invalid choice. Please try again.")


if __name__ == "__main__":
    main()
```

This program allows you to add, remove, and search for contacts in a phonebook dictionary. The user can continue to use the program until they choose to exit.
